CREATE COLUMN TABLE "TEST_AP"."OEDG" ("AbsEntry" INTEGER CS_INT NOT NULL , "Type" NVARCHAR(1) NOT NULL , "ObjType" NVARCHAR(20) DEFAULT '-1', "ObjCode" NVARCHAR(15) NOT NULL , "DiscRel" NVARCHAR(1) DEFAULT 'L', "ValidFor" NVARCHAR(1) DEFAULT 'Y', "ValidForm" LONGDATE CS_LONGDATE, "ValidTo" LONGDATE CS_LONGDATE, "DataSource" NVARCHAR(1) DEFAULT 'N', "UserSign" SMALLINT CS_INT, "LogInstanc" INTEGER CS_INT DEFAULT 0, "UserSign2" SMALLINT CS_INT, "CreateDate" LONGDATE CS_LONGDATE, "UpdateDate" LONGDATE CS_LONGDATE, PRIMARY KEY ("AbsEntry")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OEDG_CODE_TYPE" ON "TEST_AP"."OEDG" ( "ObjCode" ASC, "Type" ASC )